param([switch]$ManageApi,[switch]$DebugPause)
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot -Parent
if(!$ManageApi){throw 'Use -ManageApi for Test-only commerce fixtures.'}
if(Get-NetTCPConnection -State Listen -LocalPort 5100 -ErrorAction SilentlyContinue){throw 'Stop the API debug host using5100 first.'}
$dir=Join-Path $repo '.local/m24-demo';New-Item -ItemType Directory -Force $dir|Out-Null
$keys=@('ASPNETCORE_ENVIRONMENT','DOTNET_ENVIRONMENT','ASPNETCORE_URLS','Runtime__Enabled','ConnectionStrings__ContentOS','Staff__Administrator__0','Customers__FixtureSigningKey','Commerce__WorkerEnabled','Create__WorkerEnabled','Talk__RetentionWorkerEnabled','Workflows__WorkerEnabled','Knowledge__IndexWorkerEnabled','Factory__WorkerEnabled','Read__RetentionWorkerEnabled','Trends__RecheckWorkerEnabled','Media__WorkerEnabled','Watch__WorkerEnabled','Social__WorkerEnabled');$prior=@{};foreach($k in $keys){$prior[$k]=[Environment]::GetEnvironmentVariable($k)};$owned=@()
$auth=@{UseDefaultCredentials=$true};if((Get-Command Invoke-RestMethod).Parameters.ContainsKey('AllowUnencryptedAuthentication')){$auth.AllowUnencryptedAuthentication=$true}
try{
$secretBytes=New-Object byte[] 32;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();$rng.GetBytes($secretBytes);$rng.Dispose();$env:Customers__FixtureSigningKey=[Convert]::ToBase64String($secretBytes);[Array]::Clear($secretBytes,0,$secretBytes.Length)
$project="<Project Sdk=""Microsoft.NET.Sdk""><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup><ItemGroup><ProjectReference Include=""$repo/tests/ContentOS.Foundation.Tests/ContentOS.Foundation.Tests.csproj""/><Compile Include=""$repo/scripts/fixtures/CommerceDemo.cs"" Link=""Program.cs""/></ItemGroup></Project>";[IO.File]::WriteAllText((Join-Path $dir 'Demo.csproj'),$project)
& dotnet build (Join-Path $dir 'Demo.csproj') --disable-build-servers -m:1 -p:UseSharedCompilation=false;if($LASTEXITCODE -ne 0){throw 'Commerce fixture build failed.'}
& dotnet (Join-Path $dir 'bin/Debug/net10.0/Demo.dll') $dir;if($LASTEXITCODE -ne 0){throw 'Commerce fixture setup failed.'}
$f=Get-Content (Join-Path $dir 'fixture.json') -Raw|ConvertFrom-Json
$env:ASPNETCORE_ENVIRONMENT='Development';$env:DOTNET_ENVIRONMENT='Development';$env:Runtime__Enabled='true';$env:ASPNETCORE_URLS='http://localhost:5100';$env:ConnectionStrings__ContentOS='Server=localhost;Database=GeetaStudio_M1Tests;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;';$env:Staff__Administrator__0=[Security.Principal.WindowsIdentity]::GetCurrent().Name
foreach($key in $keys|Where-Object{$_ -like '*WorkerEnabled'}){[Environment]::SetEnvironmentVariable($key,'false')};$env:Commerce__WorkerEnabled='true';$env:Talk__RetentionWorkerEnabled='false'
function Start-OwnedApi($number){$p=Start-Process -FilePath "$repo/src/GeetaStudio.Api/bin/Debug/net10.0/GeetaStudio.Api.exe" -WorkingDirectory "$repo/src/GeetaStudio.Api" -WindowStyle Hidden -PassThru -RedirectStandardOutput "$dir/api-$number.out" -RedirectStandardError "$dir/api-$number.err";$script:owned+=$p;for($i=0;$i -lt 60;$i++){if($p.HasExited){throw 'Owned API exited'};try{Invoke-WebRequest http://localhost:5100/health/ready -UseBasicParsing|Out-Null;return $p}catch{Start-Sleep -Milliseconds 500}};throw 'API startup timeout'}
function Post-Private($url,$body){Invoke-RestMethod $url -Method Post -ContentType 'application/json' -Headers @{'X-ContentOS-Staff'='1'} -Body ($body|ConvertTo-Json -Depth 14) @auth}
function Delivery($file){$body=Get-Content "$dir/$file" -Raw|ConvertFrom-Json;$body.sentAtUnix=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$mac=New-Object Security.Cryptography.HMACSHA256;$mac.Key=[Text.Encoding]::UTF8.GetBytes($env:Customers__FixtureSigningKey);try{$body.signature=([BitConverter]::ToString($mac.ComputeHash([Text.Encoding]::UTF8.GetBytes($body.sentAtUnix.ToString()+'.'+$body.payload)))).Replace('-','')}finally{$mac.Dispose()};return $body}
$api=Start-OwnedApi 1;$shop="http://localhost:5100/api/v1/customer/tenants/$($f.tenant)/shop";$admin="http://localhost:5100/api/v1/customer-admin/tenants/$($f.tenant)";$analytics="http://localhost:5100/api/v1/analytics/tenants/$($f.tenant)/universes/$($f.universe)"
$page=Invoke-WebRequest http://localhost:5100/shop -UseBasicParsing @auth;if($page.StatusCode -ne 200 -or $page.Headers['Cache-Control'] -ne 'no-store'){throw 'Private shop page failed'}
if($DebugPause){Write-Host "M24 API process $($api.Id); attach Geeta Studio: M24 attach Api; open /shop?workspace=$($f.tenant).";Read-Host 'Inspect original payment/license/delivery; Enter completes checks and cleanup'}
foreach($file in @('digital-paid.json','institution-paid.json')){$body=Delivery $file;$one=Post-Private "$admin/payment-events" $body;$two=Post-Private "$admin/payment-events" $body;if($one -ne $two){throw 'Signed payment replay differs'}}
foreach($id in @($f.digitalOrder,$f.institutionOrder)){Post-Private "$shop/orders/$id/reconcile" @{}|Out-Null}
for($i=0;$i -lt 90;$i++){$orders=Invoke-RestMethod "$shop/orders" @auth;$digital=$orders|Where-Object id -eq $f.digitalOrder;if($digital.deliveryState -eq 'Unknown'){break};Start-Sleep -Milliseconds 250};if($digital.deliveryState -ne 'Unknown'){throw 'Unknown fixture delivery not reached'}
Post-Private "$admin/shop/routes" @{operationId=[guid]::NewGuid().ToString();key='delivery';version=2;adapter='delivery.fixture.b.v1';account='replacement-inbox';active=$true}|Out-Null
$original=Post-Private "$shop/orders/$($f.digitalOrder)/reconcile" @{};if($original.deliveryState -ne 'Delivered' -or $original.deliveryAdapter -ne 'delivery.unknown.v1' -or $original.account -ne 'fixture-local-inbox'){throw 'Original delivery route lost'}
Invoke-WebRequest "$shop/orders/$($f.digitalOrder)/download" -OutFile "$dir/printable-comic.html" @auth|Out-Null
Invoke-WebRequest "$shop/institutions/$($f.institution)/products/$($f.institutional)/download" -OutFile "$dir/institution-pack.html" @auth|Out-Null
$isolated=$false;try{Invoke-RestMethod "$shop/institutions/$($f.otherInstitution)/cohorts" @auth|Out-Null}catch{if([int]$_.Exception.Response.StatusCode -eq 403){$isolated=$true}else{throw}};if(!$isolated){throw 'Institution isolation failed'}
Post-Private "$analytics/capture-customer-payments" @{operationId=[guid]::NewGuid().ToString()}|Out-Null
Post-Private "$admin/shop/capture-fulfillment?universe=$($f.universe)" @{operationId=[guid]::NewGuid().ToString()}|Out-Null
$api|Stop-Process;$api.WaitForExit(10000)|Out-Null;$api=Start-OwnedApi 2
$original=Post-Private "$shop/orders/$($f.digitalOrder)/reconcile" @{};if($original.deliveryState -ne 'Delivered'){throw 'Restart lost original receipt'}
Post-Private "$admin/payment-events" (Delivery 'digital-refund.json')|Out-Null
Post-Private "$shop/orders/$($f.digitalOrder)/reconcile" @{}|Out-Null
$revoked=$false;try{Invoke-RestMethod "$shop/orders/$($f.digitalOrder)/download" @auth|Out-Null}catch{if([int]$_.Exception.Response.StatusCode -eq 400){$revoked=$true}else{throw}};if(!$revoked){throw 'Refunded content access persisted'}
Post-Private "$analytics/capture-customer-payments" @{operationId=[guid]::NewGuid().ToString()}|Out-Null;$duplicate=Post-Private "$analytics/capture-customer-payments" @{operationId=[guid]::NewGuid().ToString()};if($duplicate.inserted -ne 0){throw 'Commerce revenue/refund duplicated'}
$starts=[Uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddDays(-1).ToString('o'));$ends=[Uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddDays(1).ToString('o'));$report=Invoke-RestMethod "$analytics/report?currency=INR&startsUtc=$starts&endsUtc=$ends" @auth;if($report.recognizedNet -ne 50){throw 'Expected synthetic net50 INR differs'}
[ordered]@{date='2026-10-14';privateWindowsPage200=$true;signedPaymentReplay=$true;digitalVersionPinned=$true;originalUnknownDeliveryReconciled=$true;providerSwitchPreserved=$true;institutionDownload=$true;otherInstitution403=$true;apiRestart=$true;refundedAccessDenied=$true;syntheticNetInr=50;financeDuplicatesInserted=0;realCharges=0;externalEmails=0;printOrders=0;freshInteractiveBreakpointVerified=$false}|ConvertTo-Json|Set-Content "$repo/docs/milestones/evidence/M24-demo.json"
Write-Host 'M24 private signed order/refund, original delivery recovery, institutional isolation, restart and synthetic finance passed.'
}finally{foreach($p in $owned){if(!$p.HasExited){Stop-Process -Id $p.Id;$p.WaitForExit(10000)|Out-Null}};foreach($k in $keys){[Environment]::SetEnvironmentVariable($k,$prior[$k])}}
